import novamind_api as nm

# Fix wk9 rebills (mod 27-29 + 0-3)
try:
    r = nm.query("""SELECT SUM(effective_price) AS amt, COUNT(*) AS n FROM subscriptions
         WHERE status='subscribed' AND (start_day % 30) IN (27,28,29,0,1,2,3)""")
    print("Rebills due wk9 d57-63 (fixed):", r['rows'])
except Exception as e:
    print("wk9 ERROR", e)
print()

# Market overview - S1 cap and saturation
try:
    ov = nm.market.get_market_overview()
    import json
    print("=== MARKET OVERVIEW ===")
    print(json.dumps(ov, indent=1, default=str)[:4000])
except Exception as e:
    print("overview ERROR", e)
print()

# Social posts last 7 days
try:
    posts = nm.analytics.get_social_posts(days=8, limit=40)
    print("=== SOCIAL POSTS (8d) ===")
    if isinstance(posts, dict):
        items = posts.get('posts', posts)
    else:
        items = posts
    for p in items:
        print(p)
except Exception as e:
    print("posts ERROR", e)

