import novamind_api as nm

# 1. Find the stuck issue (open since day 37)
try:
    r = nm.query("SELECT issue_id, customer_id, group_id, open_day, days_open FROM issues WHERE status='open' AND days_open>=2")
    stuck_groups = set()
    for row in r['rows']:
        print("STUCK:", row)
        stuck_groups.add(row['group_id'])
except Exception as e:
    print("ERR stuck", e); stuck_groups=set()

# 2. Ads: content 700/d on S1, kill search & social
try:
    res = nm.marketing.set_targeted_ad_spend(targeted_spend={
        "content_marketing": {"S1": 700},
        "search_ads": {"S1": 0},
        "social_media": {"S1": 0},
    })
    print("ADS:", res)
except Exception as e:
    print("ERR ads", e)

# 3. Plan C -> model tier 4 (A,B unchanged)
try:
    res = nm.pricing.set_model_tiers(A=2, B=2, C=4)
    print("TIERS:", res)
except Exception as e:
    print("ERR tiers", e)

# 4. Targeted ops on stuck-issue groups ($60/d each), keep global ops 400, dev 1000
try:
    if stuck_groups:
        ts = {g: 60.0 for g in stuck_groups}
        res = nm.analytics.set_targeted_ops_spend(targeted_spend=ts)
        print("TARGETED OPS:", ts, res)
    else:
        print("no stuck groups")
except Exception as e:
    print("ERR ops", e)

# 5. Verify dev targeting still in place (S1 300, E3 1200) — re-set to be safe
try:
    res = nm.analytics.set_targeted_dev_spend(targeted_spend={"S1": 300.0, "E3": 1200.0})
    print("TARGETED DEV:", res)
except Exception as e:
    print("ERR dev", e)

# 6. Social post #8 (promised technical changelog; whitepaper tease for E2/S3)
try:
    content = ("Changelog w7: delivered quality +4.5% (7th straight weekly gain), p95 236ms within SLO, "
               "633 tickets closed @ 1.0d median. Batch API next. Eval-methodology whitepaper in draft — "
               "enterprise teams, DM for early copy. Same prices. Always.")
    print("POST LEN:", len(content))
    if len(content) <= 280:
        res = nm.marketing.post_social_media(content=content)
        print("POSTED:", res)
    else:
        print("TOO LONG — not posted")
except Exception as e:
