import novamind_api as nm
from statistics import NormalDist
from collections import defaultdict
nd = NormalDist()

def sec(t): print("\n===== "+t+" =====")

sec("SCHEMA PEEK")
for t in ["subscriptions","ledger"]:
    try:
        r = nm.query("SELECT * FROM "+t+" LIMIT 1")
        print(t, list(r['rows'][0].keys()) if r['rows'] else "EMPTY")
    except Exception as e:
        print(t,"ERR",e)

sec("POSTS BY DAY/SOURCE d77+")
try:
    r = nm.query("SELECT day, COALESCE(source_group_id,'NONE') g, COUNT(*) n FROM social_media_posts WHERE day>=77 GROUP BY day,g ORDER BY day")
    for row in r['rows']: print(row['day'], row['g'], row['n'])
except Exception as e: print("ERR",e)

sec("NON-CUSTOMER POSTS d77+ (competitor/system)")
try:
    r = nm.query("SELECT post_id,day,COALESCE(source_group_id,'NONE') g,content FROM social_media_posts WHERE day>=77 AND (source_group_id IS NULL OR source_group_id NOT IN ('S1','S2','S3','E1','E2','E3')) ORDER BY day LIMIT 80")
    for row in r['rows']: print(row['day'],"|",row['g'],"|",row['content'][:160])
except Exception as e: print("ERR",e)

sec("S1 DAILY CONV + MU FIT d78-84")
try:
    rows = nm.query("SELECT c.created_day d, COUNT(*) leads, SUM(CASE WHEN s.customer_id IS NOT NULL THEN 1 ELSE 0 END) subs FROM customers c LEFT JOIN (SELECT DISTINCT customer_id FROM subscriptions) s ON s.customer_id=c.customer_id WHERE c.created_day>=78 AND c.group_id='S1' GROUP BY c.created_day ORDER BY d")['rows']
    for row in rows:
        d=row['d']; L=row['leads']; S=row['subs']; conv=S/L if L else 0
        delivered=(0.20+0.1768+0.1255+0.00521*(d-77))*0.75
        z=nd.inv_cdf(min(max(conv+0.03,1e-4),0.9999))
        mu=delivered-0.06*z
        print(d,"leads",L,"subs",S,"conv",round(conv,3),"delivered",round(delivered,4),"mu",round(mu,4))
except Exception as e: print("ERR",e)

sec("LEADS BY GROUP d78-84")
try:
    r = nm.query("SELECT c.group_id g, COUNT(*) leads, SUM(CASE WHEN s.customer_id IS NOT NULL THEN 1 ELSE 0 END) subs FROM customers c LEFT JOIN (SELECT DISTINCT customer_id FROM subscriptions) s ON s.customer_id=c.customer_id WHERE c.created_day>=78 GROUP BY g")
    for row in r['rows']: print(row)
except Exception as e: print("ERR",e)

sec("S1 CONV BY SOURCE d78-84")
try:
    r = nm.query("SELECT c.acquisition_source src, COUNT(*) leads, SUM(CASE WHEN s.customer_id IS NOT NULL THEN 1 ELSE 0 END) subs FROM customers c LEFT JOIN (SELECT DISTINCT customer_id FROM subscriptions) s ON s.customer_id=c.customer_id WHERE c.created_day>=78 AND c.group_id='S1' GROUP BY src")
    for row in r['rows']: print(row)
except Exception as e: print("ERR",e)

sec("LEDGER WK12 (d78-84)")
try:
    peek = nm.query("SELECT * FROM ledger LIMIT 1")['rows']
    cols = list(peek[0].keys()) if peek else []
    print("cols:",cols)
    catcol = None
    for c in ["category","type","kind","entry_type","reason"]:
        if c in cols: catcol=c; break
    if catcol:
        r = nm.query("SELECT "+catcol+" cat, SUM(amount) s, COUNT(*) n FROM ledger WHERE day BETWEEN 78 AND 84 GROUP BY cat ORDER BY s")
        tin=0; tout=0
        for row in r['rows']:
            print(row['cat'], round(row['s'],1), row['n'])
            if row['s']>0: tin+=row['s']
            else: tout+=row['s']
        print("IN",round(tin,1),"OUT",round(tout,1),"NET",round(tin+tout,1))
except Exception as e: print("ERR",e)

sec("ISSUES d70-84 daily + backlog")
try:
    r = nm.query("SELECT open_day, COUNT(*) n, SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) res, ROUND(AVG(days_open),3) avg_open FROM issues WHERE open_day>=70 GROUP BY open_day ORDER BY open_day")
    for row in r['rows']: print(row)
    r2 = nm.query("SELECT status, COUNT(*) n FROM issues GROUP BY status")
    print("status:", r2['rows'])
except Exception as e: print("ERR",e)

sec("REBILL SCHEDULE (active subs) d85-147")
try:
    rows = nm.query("SELECT created_day cd, COUNT(*) n, SUM(price) p FROM subscriptions WHERE status='active' GROUP BY created_day")['rows']
    wk=defaultdict(lambda:[0,0.0])
    for row in rows:
        cd=row['cd']; n=row['n']; p=row['p'] if row['p'] else n*12.0
        k=1
        while cd+30*k<=147:
            rd=cd+30*k
            if rd>=85:
                w=(rd-85)//7
                wk[w][0]+=n; wk[w][1]+=p
            k+=1
    for w in sorted(wk):
        print("d"+str(85+7*w)+"-"+str(91+7*w), wk[w][0], "rebills $"+str(round(wk[w][1])))
except Exception as e: print("ERR",e)

sec("ENTERPRISE TURNS OPEN")
try:
    r = nm.query("SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0")
    print(r['rows'])
except Exception as e: print("ERR",e)

sec("CONFIG OVERRIDES (last 15)")
try:
    r = nm.query("SELECT * FROM config_overrides ORDER BY rowid DESC LIMIT 15")
    for row in r['rows']: print(row)
except Exception as e: print("ERR",e)

sec("ACTIVE SUBS")
try:
    r = nm.query("SELECT COUNT(*) n FROM subscriptions WHERE status='active'")
    print("active subs:", r['rows'][0]['n'])
except Exception as e: print("ERR",e)
