import novamind_api as nm
from math import erf, sqrt
import json

def phi(x): return 0.5*(1+erf(x/sqrt(2)))
def phi_inv(p):
    lo, hi = -6.0, 6.0
    for _ in range(80):
        mid = (lo+hi)/2
        if phi(mid) < p: lo = mid
        else: hi = mid
    return (lo+hi)/2

print("=== DAY", nm.vars.current_day, "===")

# ---------- 1. Social posts (competitor events d85-91) ----------
print("\n---------- SOCIAL POSTS last 8 days ----------")
try:
    posts = nm.analytics.get_social_posts(days=8, limit=100)
    if isinstance(posts, dict):
        rows = posts.get('posts', posts.get('rows', []))
    else:
        rows = posts
    for p in rows:
        try:
            print(f"d{p.get('day','?')} | {p.get('author_type',p.get('author','?'))} | grp={p.get('group_id','?')} | likes={p.get('likes','?')} | {str(p.get('content',''))[:160]}")
        except Exception as e:
            print("rowerr", e, str(p)[:200])
except Exception as e:
    print("ERR posts:", e)

# ---------- 2. Daily S1 conversion d85-91 ----------
