        FROM customers c JOIN subscriptions s ON s.customer_id = c.customer_id
        WHERE c.group_id='S1' AND c.created_day BETWEEN 85 AND 91
        GROUP BY c.created_day ORDER BY d
    """)
    print("d | n | conv | rate | z | mu_est($10)")
    for row in r['rows']:
        d, n, cv = row['d'], row['n'], row['conv']
        rate = cv/n if n else 0
        delivered = 0.4327 - 0.004086*(91-d)
        z = phi_inv(min(max(rate+0.03, 1e-4), 1-1e-4))
        mu = delivered - 0.060*z
        print(f"{d} | {n} | {cv} | {rate:.3f} | {z:+.3f} | {mu:.4f}")
