import novamind_api as nm

# A. Ledger week 15 (days 98-104) by category
try:
    r = nm.query('SELECT category, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day>=98 AND day<=104 GROUP BY category ORDER BY amt')
    print('--- LEDGER wk15 (d98-104):')
    for row in r['rows']: print(f\"  {row['category']:28s} {row['amt']:>12.0f}  n={row['n']}\")
except Exception as e: print('ERR ledger:', e)

# B. Daily signups & leads (conv by day) - subscriptions started per day
try:
    r = nm.query(\"SELECT start_day as d, COUNT(*) as n FROM subscriptions WHERE start_day>=98 GROUP BY start_day ORDER BY d\")
    subs_by_day = {row['d']: row['n'] for row in r['rows']}
    r2 = nm.query('SELECT created_day as d, COUNT(*) as n FROM customers WHERE created_day>=98 AND customer_type=\'small\' GROUP BY created_day ORDER BY d')
    leads_by_day = {row['d']: row['n'] for row in r2['rows']}
    print('--- Daily: leads -> new subs (conv):')
    for d in sorted(leads_by_day):
        L=leads_by_day.get(d,0); S=subs_by_day.get(d,0)
        print(f'  d{d}: leads={L:4d} subs={S:3d} conv={S/max(L,1):.3f}')
except Exception as e: print('ERR conv:', e)

# C. Cancellations by day (end_day)
try:
    r = nm.query(\"SELECT end_day as d, COUNT(*) as n FROM subscriptions WHERE status='cancelled' AND end_day>=91 GROUP BY end_day ORDER BY d\")
    print('--- Cancels by day (since d91):')
    for row in r['rows']: print(f\"  d{row['d']}: {row['n']}\")
except Exception as e: print('ERR cancels:', e)

# D. Active book snapshot
try:
    r = nm.query(\"SELECT plan, effective_price, COUNT(*) as n FROM subscriptions WHERE status='subscribed' GROUP BY plan, effective_price ORDER BY n DESC LIMIT 12\")
    print('--- Active book by plan/price:')
    for row in r['rows']: print(f\"  {row['plan']} @ {row['effective_price']}: {row['n']}\")
except Exception as e: print('ERR book:', e)

# E. Upcoming rebills by week (gross $) from billing_day_mod30
try:
    r = nm.query(\"\"\"
    SELECT ((CASE WHEN billing_day_mod30 >= 105%30 THEN 105 + (billing_day_mod30 - 105%30)
                  ELSE 105 + 30 - (105%30 - billing_day_mod30) END) - 105)/7 as wk_ahead,
           SUM(effective_price*seat_count) as gross, COUNT(*) as n
    FROM subscriptions WHERE status='subscribed'
    GROUP BY wk_ahead ORDER BY wk_ahead
    \"\"\")
    print('--- Rebills due by week ahead (gross):')
    for row in r['rows']: print(f\"  wk+{row['wk_ahead']}: {row['gross']:>8.0f} ({row['n']} subs)\")
except Exception as e: print('ERR rebills:', e)
