import novamind_api as nm
import json
from collections import defaultdict

def sec(t):
    print("\n" + "="*60)
    print(t)
    print("="*60)

# 1. Ledger by day/category d139+
try:
    sec("1. LEDGER d139-147 by day/category")
    r = nm.query("SELECT day, category, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day>=139 GROUP BY day, category ORDER BY day, category")
    for row in r['rows']:
        print(row['day'], row['category'], round(row['amt'],1), row['n'])
except Exception as e:
    print("ERR1", e)

# 1b. all-time categories (check for any ad-revenue category)
try:
    sec("1b. ALL LEDGER CATEGORIES all-time")
    r = nm.query("SELECT category, SUM(amount) as amt, COUNT(*) as n FROM ledger GROUP BY category")
    for row in r['rows']:
        print(row['category'], round(row['amt'],1), row['n'])
except Exception as e:
    print("ERR1b", e)

# 2. Cancels by end_day/plan
try:
    sec("2. CANCELS by end_day/plan d139+")
    r = nm.query("SELECT end_day, plan, COUNT(*) as n FROM subscriptions WHERE status='cancelled' AND end_day>=139 GROUP BY end_day, plan ORDER BY end_day, plan")
    tot = defaultdict(int)
    for row in r['rows']:
        print(row['end_day'], row['plan'], row['n'])
        tot[row['plan']] += row['n']
    print("totals:", dict(tot))
except Exception as e:
    print("ERR2", e)

# 3. Payments by day & amount
try:
    sec("3. SUBSCRIPTION PAYMENTS by day/amount d140+")
    r = nm.query("SELECT day, amount, COUNT(*) as n FROM ledger WHERE category='subscription_payment' AND day>=140 GROUP BY day, amount ORDER BY day, amount")
    for row in r['rows']:
        print(row['day'], row['amount'], row['n'])
except Exception as e:
    print("ERR3", e)

# 4. Active book
try:
    sec("4. ACTIVE BOOK by plan/price")
    r = nm.query("SELECT plan, effective_price, COUNT(*) as n FROM subscriptions WHERE status='subscribed' GROUP BY plan, effective_price ORDER BY plan, effective_price")
    for row in r['rows']:
        print(row['plan'], row['effective_price'], row['n'])
except Exception as e:
    print("ERR4", e)

# 5. Fresh dues by week
try:
    sec("5. DUES by week (fresh, active subs)")
    r = nm.query("SELECT plan, effective_price, billing_day_mod30, COUNT(*) as n FROM subscriptions WHERE status='subscribed' GROUP BY plan, effective_price, billing_day_mod30")
    rows = r['rows']
    wk = defaultdict(lambda: defaultdict(int))
    for d in range(147, 147+7*8):
        m = d % 30
        w = (d-147)//7
        for row in rows:
            if row['billing_day_mod30'] == m:
                key = f"{row['plan']}@{int(row['effective_price'])}"
                wk[w][key] += row['n']
    for w in sorted(wk):
        items = dict(sorted(wk[w].items()))
        rev = sum((float(k.split('@')[1]))*v for k,v in items.items())
        print(f"wk{22+w} d{147+7*w}-{147+7*w+6}: {items}  max_rev=${rev:,.0f}")
except Exception as e:
    print("ERR5", e)

# 6. Usage by day/plan
try:
    sec("6. USAGE by day/plan d140-146")
    r = nm.query("SELECT du.day as day, s.plan as plan, SUM(du.usage_units) as u, COUNT(DISTINCT du.customer_id) as c FROM daily_usage du JOIN subscriptions s ON du.customer_id=s.customer_id WHERE du.day>=140 AND s.status='subscribed' GROUP BY du.day, s.plan ORDER BY du.day, s.plan")
    daytot = defaultdict(float)
    for row in r['rows']:
        print(row['day'], row['plan'], int(row['u']), row['c'], round(row['u']/max(1,row['c']),1))
        daytot[row['day']] += row['u']
    for d in sorted(daytot):
        print(f"day {d} total {int(daytot[d])} -> compute est A/B/C mix")
except Exception as e:
    print("ERR6", e)

# 7. Enterprise turns
try:
    sec("7. ENTERPRISE TURNS count")
    r = nm.query("SELECT COUNT(*) as n FROM enterprise_turns")
    print("total:", r['rows'])
    r2 = nm.query("SELECT COUNT(*) as n FROM enterprise_turns WHERE closed=0")
    print("open:", r2['rows'])
except Exception as e:
    print("ERR7", e)

# 8. Social posts
try:
    sec("8. SOCIAL POSTS last 8d")
    posts = nm.analytics.get_social_posts(days=8, limit=80)
    if isinstance(posts, dict):
        plist = posts.get('posts', posts.get('rows', []))
    else:
        plist = posts
    for p in plist:
        if isinstance(p, dict):
            day = p.get('day', '?')
            author = p.get('author_type', p.get('author', '?'))
            content = str(p.get('content',''))[:110].replace('\n',' ')
            print(f"d{day} [{author}] {content}")
except Exception as e:
    print("ERR8", e)

# 9. Recent leads by group/status
try:
    sec("9. LEADS d140+ by group/status")
