import novamind_api as nm
from collections import defaultdict

def sec(t):
    print("\n" + "="*60)
    print(t)
    print("="*60)

# A. ads_revenue table — have we ever earned in-app ad revenue?
try:
    sec("A. ADS REVENUE all-time")
    r = nm.query("SELECT COUNT(*) as n, SUM(revenue) as rev, MIN(day) as d0, MAX(day) as d1 FROM ads_revenue")
    print(r['rows'])
except Exception as e:
    print("ERRA", e)

# B. Leads d140+ by group/status (rerun, got truncated)
try:
    sec("B. LEADS d140+ by group/status")
    r = nm.query("SELECT c.group_id as g, s.status as st, COUNT(*) as n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=140 GROUP BY c.group_id, s.status ORDER BY c.group_id")
    for row in r['rows']:
        print(row['g'], row['st'], row['n'])
except Exception as e:
    print("ERRB", e)

# C. Usage distribution vs quota on d147 (weekday). Quotas: A=200 B=650 C=140
try:
    sec("C. USAGE DISTRIBUTION d147 (subscribed only)")
    for plan, quota in [('A',200),('B',650),('C',140)]:
        r = nm.query(f"SELECT COUNT(*) as n, SUM(CASE WHEN du.usage_units>={quota} THEN 1 ELSE 0 END) as at_cap, SUM(CASE WHEN du.usage_units>={int(quota*0.9)} THEN 1 ELSE 0 END) as near_cap, MAX(du.usage_units) as mx, AVG(du.usage_units) as avg FROM daily_usage du JOIN subscriptions s ON du.customer_id=s.customer_id WHERE du.day=147 AND s.status='subscribed' AND s.plan='{plan}'")
        row = r['rows'][0]
        print(f"plan {plan} quota {quota}: n={row['n']} at_cap={row['at_cap']} near90%={row['near_cap']} max={row['mx']} avg={round(row['avg'],1)}")
except Exception as e:
    print("ERRC", e)

# D. Did C churners hit the cap before cancelling? C cancels d143-147, usage on d142 (weekday)
try:
    sec("D. C CANCELLERS d143-147: usage on d142")
    r = nm.query("SELECT du.usage_units as u, COUNT(*) as n FROM subscriptions s JOIN daily_usage du ON du.customer_id=s.customer_id AND du.day=142 WHERE s.status='cancelled' AND s.plan='C' AND s.end_day BETWEEN 143 AND 147 GROUP BY du.usage_units ORDER BY du.usage_units")
    tot=0; cap=0
    for row in r['rows']:
        tot+=row['n']
        if row['u']>=140: cap+=row['n']
        print("usage", row['u'], "n", row['n'])
    print(f"total {tot}, at cap(>=140): {cap}")
except Exception as e:
    print("ERRD", e)

# D2. Compare: C renewers d143-147 usage on d142
try:
    sec("D2. C RENEWERS (still subscribed, billed d143-147): usage d142")
    r = nm.query("SELECT SUM(CASE WHEN du.usage_units>=140 THEN 1 ELSE 0 END) as at_cap, COUNT(*) as n FROM subscriptions s JOIN daily_usage du ON du.customer_id=s.customer_id AND du.day=142 WHERE s.status='subscribed' AND s.plan='C' AND s.billing_day_mod30 IN (23,24,25,26,27) ")
    print(r['rows'])
except Exception as e:
    print("ERRD2", e)

# E. Issues: open by group, opened/resolved rates last week, avg days_open
try:
    sec("E. ISSUES: open now by group; resolution speed")
    r = nm.query("SELECT group_id, COUNT(*) as n, AVG(days_open) as avg_open FROM issues WHERE status='open' GROUP BY group_id")
    for row in r['rows']:
        print("open:", row['group_id'], row['n'], round(row['avg_open'],1))
    r = nm.query("SELECT resolved_day, COUNT(*) as n FROM issues WHERE resolved_day>=140 GROUP BY resolved_day ORDER BY resolved_day")
    for row in r['rows']:
        print("resolved d", row['resolved_day'], row['n'])
    r = nm.query("SELECT open_day, COUNT(*) as n FROM issues WHERE open_day>=140 GROUP BY open_day ORDER BY open_day")
    for row in r['rows']:
        print("opened d", row['open_day'], row['n'])
except Exception as e:
    print("ERRE", e)

# F. Issue-churn link: of C cancels d141-147, how many had an open issue?
try:
    sec("F. C cancels d141-147 with open issue at cancel")
    r = nm.query("SELECT COUNT(DISTINCT s.customer_id) as n FROM subscriptions s JOIN issues i ON i.customer_id=s.customer_id AND i.status='open' WHERE s.status='cancelled' AND s.plan='C' AND s.end_day BETWEEN 141 AND 147")
    print("C cancellers w/ open issue:", r['rows'])
    r = nm.query("SELECT COUNT(DISTINCT s.customer_id) as n FROM subscriptions s JOIN issues i ON i.customer_id=s.customer_id AND i.status='open' WHERE s.status='subscribed' AND s.plan='C'")
    print("active C subs w/ open issue:", r['rows'])
except Exception as e:
    print("ERRF", e)

# G. dues per DAY next 10 days (precise forecast)
try:
    sec("G. DUES per day d148-160")
    r = nm.query("SELECT plan, effective_price, billing_day_mod30, COUNT(*) as n FROM subscriptions WHERE status='subscribed' GROUP BY plan, effective_price, billing_day_mod30")
    rows = r['rows']
    for d in range(148, 161):
        m = d % 30
        parts = defaultdict(int)
        for row in rows:
            if row['billing_day_mod30']==m:
                parts[f"{row['plan']}@{int(row['effective_price'])}"] += row['n']
        print(f"d{d} (mod {m}): {dict(parts)}")
except Exception as e:
    print("ERRG", e)

