import novamind_api as nm
import json

# 1. C -> T4 (saves ~$4.9K/wk compute; delivered .6916 vs R_raw(49)~.653 + loyalty)
try:
    r = nm.pricing.set_model_tiers(A=2, B=3, C=4)
    print("TIERS:", r)
except Exception as e:
    print("ERR tiers", e)

# 2. Targeted dev S1 1000 -> 300 (+.0013/d raw, ~2x R-drift net of global decay)
try:
    r = nm.analytics.set_targeted_dev_spend(targeted_spend={"S1": 300.0})
    print("DEV S1 300:", r)
except Exception as e:
    print("ERR dev", e)

# 3. Targeted ops S1 -> 0
try:
    r = nm.analytics.set_targeted_ops_spend(targeted_spend={"S1": 0.0})
    print("OPS S1 0:", r)
except Exception as e:
    print("ERR ops targeted", e)

# 4. Global ops 500 -> 400, dev global stays 0
try:
    r = nm.marketing.set_daily_spend(operations=400, development=0)
    print("DAILY SPEND:", r)
except Exception as e:
    print("ERR daily spend", e)

# 5. ADS ROLLOUT: all 1916 A-plan subs at 0.3 (cohort dose unchanged); C/B stay 0
try:
    ids = json.load(open('a_plan_ids.json'))
    by_cust = {str(i): 0.3 for i in ids}
    r = nm.marketing.set_ads_strength(global_strength=0.0, by_customer=by_cust)
    s = str(r)
    print("ADS STRENGTH:", s[:300])
    print("N set:", len(by_cust))
except Exception as e:
    print("ERR ads", e)

