import novamind_api as nm
from collections import defaultdict

def q(sql, tag=""):
    try:
        return nm.query(sql)['rows']
    except Exception as e:
        print(f"ERR[{tag}] {e}")
        return []

day = nm.vars.current_day
print("=== DAY", day, "===")
D0, D1 = day-6, day

r = q("SELECT * FROM subscriptions LIMIT 1", "p1")
subcols = sorted(r[0].keys()) if r else []
print("SUBCOLS:", subcols)

print("\n=== 1 LEDGER by category (wk) ===")
tot = 0.0
for row in q(f"SELECT category c, COUNT(*) n, SUM(amount) s FROM ledger WHERE day BETWEEN {D0} AND {D1} GROUP BY c ORDER BY s", "led"):
    print(f"{str(row['c']):26s} n={row['n']:5d} s={row['s']:10.1f}")
    tot += row['s']
print(f"NET {tot:.0f}")

print("\n=== 2 PAYMENTS by amount ===")
for row in q(f"SELECT amount a, COUNT(*) n FROM ledger WHERE day BETWEEN {D0} AND {D1} AND category='subscription_payment' GROUP BY a ORDER BY a", "pay"):
    print(f"${row['a']:7.2f} x {row['n']:4d} = {row['a']*row['n']:9.0f}")

print("\n=== 3 DAILY compute (usage proxy) ===")
for row in q(f"SELECT day d, -SUM(amount) s FROM ledger WHERE category='compute' AND day BETWEEN {D0} AND {D1} GROUP BY d ORDER BY d", "comp"):
    print(f"d{row['d']}: {row['s']:8.1f}")

dcol = next((c for c in ['end_day','cancel_day','cancelled_day','close_day','churn_day','last_day'] if c in subcols), None)
print(f"\n=== 4 CANCELS this wk (col={dcol}) ===")
if dcol:
    for row in q(f"SELECT plan p, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND {dcol} BETWEEN {D0} AND {D1} GROUP BY p", "canc"):
        print(f"plan {row['p']}: {row['n']}")

print("\n=== 5 ACTIVE MIX plan@price ===")
tot_n = 0
for row in q("SELECT plan p, effective_price e, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY p,e ORDER BY p,e", "mix"):
    print(f"{row['p']} @{row['e']:5.1f}: {row['n']:5d}")
    tot_n += row['n']
print("TOTAL", tot_n)

print("\n=== 6 DUES next 8 wks (A=$12,B=$39,C=$44) ===")
rows = q("SELECT billing_day_mod30 m, plan p, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY m,p", "dues")
bym = defaultdict(dict)
for r2 in rows:
    bym[int(r2['m'])][r2['p']] = int(r2['n'])
PRICE = {'A':12.0,'B':39.0,'C':44.0}
for w in range(8):
    ws, we = day+1+7*w, day+7+7*w
    agg = defaultdict(int)
    for d in range(ws, we+1):
        for p, n in bym.get(d % 30, {}).items():
            agg[p] += n
    t = sum(PRICE.get(p,0)*n for p,n in agg.items())
    line = " | ".join(f"{p}:{agg[p]}" for p in sorted(agg))
    print(f"wk{26+w} d{ws}-{we}: {line}  MAX ${t:.0f}")

print("\n=== 7 LEADS this wk by status ===")
for row in q(f"SELECT status st, COUNT(*) n FROM subscriptions WHERE start_day BETWEEN {D0} AND {D1} GROUP BY st", "leads"):
    print(row['st'], row['n'])

print("\n=== 8 ISSUES ===")
for row in q(f"SELECT COUNT(*) n FROM issues WHERE open_day BETWEEN {D0} AND {D1}", "i1"): print("opened wk:", row['n'])
for row in q(f"SELECT COUNT(*) n FROM issues WHERE resolved_day BETWEEN {D0} AND {D1}", "i2"): print("resolved wk:", row['n'])
for row in q("SELECT COUNT(*) n FROM issues i JOIN subscriptions s ON i.customer_id=s.customer_id WHERE i.status='open' AND s.status='subscribed'", "i3"): print("open-on-subscribed:", row['n'])

print("\n=== 9 ENTERPRISE turns ===")
for row in q("SELECT COUNT(*) n FROM enterprise_turns", "e1"): print("total turns ever:", row['n'])

print("\n=== 10 ADS CONFIG (setter-as-getter, all should be 0) ===")
try:
    cfg = nm.marketing.set_ads_strength(global_strength=0.0)
    s = str(cfg)
    print(s[:600])
except Exception as e: print("ERRads", e)

print("\n=== 11 COST INFO ===")
try:
    print(str(nm.infrastructure.get_cost_info())[:1200])
except Exception as e: print("ERRci", e)

print("\n=== 12 S1 INSIGHTS ===")
try:
    print(str(nm.market.get_group_insights(group_id="S1"))[:2500])
except Exception as e: print("ERRs1", e)

print("\n=== 13 E3 INSIGHTS ===")
try:
    print(str(nm.market.get_group_insights(group_id="E3"))[:2500])
except Exception as e: print("ERRe3", e)

print("\n=== 14 SOCIAL last 8d ===")
try:
    posts = nm.analytics.get_social_posts(days=8, limit=25)
    pl = posts.get('posts') if isinstance(posts, dict) else posts
    for p in pl or []:
        if isinstance(p, dict):
            c = str(p.get('content',''))[:110].replace("\n"," ")
            print(f"d{p.get('day')} [{p.get('author_type', p.get('author',''))}] {c}")
        else:
            print(str(p)[:130])
except Exception as e: print("ERRsoc", e)

