# Sim v2: aggressive cut ladder, extended to d504
A_anch = {0:25,1:47,2:68,3:51,4:79,5:108,6:106,7:90,8:48,9:40,10:20,11:24,12:18,13:24,14:15,
          15:11,16:22,17:1,18:11,19:11,20:12,21:19,22:23,23:24,24:15,25:14,26:18,27:31,28:38,29:27}
A_price= {a:12.0 for a in range(30)}; A_price.update({1:11.7,2:11.9,3:11.9,4:11.8})
B_anch = {1:2,2:1,3:1,4:3,5:6,6:3,7:2,8:1,11:2,12:1,13:2,15:2,16:2,17:1,23:3,24:1,28:1}
C_anch = {0:3,1:8,2:6,3:5,4:14,5:14,6:19,7:24,8:7,9:7,10:2,11:5,12:4,13:11,14:7,15:1,16:5,
          17:4,18:3,19:3,20:4,21:7,22:9,23:2,24:5,25:5,26:2,27:6,28:5,29:10}

def payrate(plan, c, scen):
    tables = {
      'mid':  {'A':[0.33,0.27,0.23,0.20,0.18],'C':[0.65,0.55,0.48,0.45,0.43],'B':[0.30,0.25,0.22,0.20,0.20]},
      'opt':  {'A':[0.38,0.33,0.29,0.26,0.24],'C':[0.72,0.65,0.60,0.57,0.55],'B':[0.35,0.30,0.28,0.25,0.25]},
      'pess': {'A':[0.28,0.21,0.16,0.13,0.12],'C':[0.52,0.42,0.38,0.36,0.35],'B':[0.22,0.18,0.15,0.15,0.15]}}
    t = tables[scen][plan]
    return t[min(c, len(t)-1)]

def ops_sched(day):
    if day<=217: return 250
    if day<=231: return 100
    if day<=259: return 50
    return 0

def sim(scen, verbose=False):
    cash = 19462.0
    bkA = {a:[float(n),0] for a,n in A_anch.items()}
    bkB = {a:[float(n),0] for a,n in B_anch.items()}
    bkC = {a:[float(n),0] for a,n in C_anch.items()}
    adsmult = {'mid':2.2,'opt':2.6,'pess':1.7}[scen]
    out = {}
    for day in range(211, 505):
        anchor = day % 30
        book = sum(v[0] for v in bkA.values())+sum(v[0] for v in bkB.values())+sum(v[0] for v in bkC.values())
        Abook = sum(v[0] for v in bkA.values())
        rev = 0.0
        for bk, plan in ((bkA,'A'),(bkB,'B'),(bkC,'C')):
            if anchor in bk:
                n,c = bk[anchor]
                p = payrate(plan,c,scen)
                pr = A_price[anchor] if plan=='A' else (39.0 if plan=='B' else 44.0)
                rev += n*p*pr
                bk[anchor] = [n*p, c+1]
        ads = 0.059*Abook*(adsmult if day>=218 else 1.0)
        ops = ops_sched(day)
        cap = 215 if book>=460 else 85
        compute = 0.273*book
        leads = 0.0124*book
        cash += rev + ads - ops - cap - compute - leads
        if day in (217,238,294,392,504):
            out[day] = (round(cash), round(book))
        if verbose and day%28==0:
            print(f"  d{day}: cash={cash:8.0f} book={book:6.0f} A={Abook:5.0f}")
    return out

for scen in ('pess','mid','opt'):
    r = sim(scen)
    print(f"{scen:5s} d217: {r[217]} | d238: {r[238]} | d294: {r[294]} | d392: {r[392]} | d504: {r[504]}")
print()
print("mid trajectory:")
sim('mid', verbose=True)
