import novamind_api as nm

print("=== DAY:", nm.vars.current_day, "===")

# 1. Trio subscription status
try:
    r = nm.query("SELECT customer_id, plan, status, effective_price, start_day, end_day FROM subscriptions WHERE customer_id IN (4417,6001,6066) ORDER BY customer_id, start_day")
    for row in r['rows']:
        print("SUB:", row)
except Exception as e:
    print("ERR subs:", e)

# 2. Enterprise turns count
try:
    r = nm.query("SELECT COUNT(*) as n FROM enterprise_turns")
    print("ENTERPRISE TURNS EVER:", r['rows'][0]['n'])
except Exception as e:
    print("ERR ent:", e)

# 3. Any new leads/subs since d273 (rep-heal detector)
try:
    r = nm.query("SELECT status, COUNT(*) as n FROM subscriptions WHERE start_day>=273 GROUP BY status")
    print("NEW SUB ROWS since d273:", r['rows'])
except Exception as e:
    print("ERR newsubs:", e)

# 4. Ledger last 7 days
try:
    r = nm.query("SELECT * FROM ledger WHERE day>=273 ORDER BY day LIMIT 120")
    from collections import defaultdict
    agg = defaultdict(float)
    cols = None
    for row in r['rows']:
        if cols is None:
            cols = list(row.keys()); print("LEDGER COLS:", cols)
        # try common column names
        cat = row.get('category', row.get('type', '?'))
        amt = row.get('amount', 0)
        agg[cat] += amt
    for k, v in sorted(agg.items()):
        print(f"LEDGER {k}: {v:+.2f}")
except Exception as e:
    print("ERR ledger:", e)

# 5. 4417 details
try:
    r = nm.query("SELECT customer_id, group_id FROM customers WHERE customer_id=4417")
    print("4417 GROUP:", r['rows'])
except Exception as e:
    print("ERR cust:", e)

# 6. Social posts last 7 days
try:
    posts = nm.analytics.get_social_posts(days=8, limit=20)
    for p in posts if isinstance(posts, list) else posts.get('posts', []):
        print("POST:", p)
except Exception as e:
    print("ERR posts:", e)

# 7. Research projects sanity (global bonus rose 0.1601->0.1656?)
try:
    projs = nm.research.list_research_projects()
    print("RESEARCH:", projs)
except Exception as e:
    print("ERR research:", e)

