try:
    r = nm.query("SELECT day, category, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day >= 372 GROUP BY day, category ORDER BY day, category")
    for row in r['rows']:
        print(row)
except Exception as e:
    print("ledger err:", e)

# Total since d372
try:
    r = nm.query("SELECT category, SUM(amount) as amt FROM ledger WHERE day >= 372 GROUP BY category")
    print("totals since d372:", r['rows'])
except Exception as e:
    print("tot err:", e)

# 2. Enterprise turns count
try:
    r = nm.query("SELECT COUNT(*) as n FROM enterprise_turns")
    print("ent_turns total:", r['rows'])
    r = nm.query("SELECT COUNT(*) as n FROM enterprise_turns WHERE closed=0")
    print("ent_turns open:", r['rows'])
except Exception as e:
    print("ent err:", e)

